import java.util.*;

public class MapDemonstration {
    public static void main(String[] args) {
        // 1. HashMap: O(1) ops, unordered
        Map<String, Integer> hashMap = new HashMap<>();
        hashMap.put("Zebra", 1);
        hashMap.put("Apple", 2);

        // 2. LinkedHashMap: O(1) ops, insertion or access ordered
        Map<String, Integer> lruCache = new LinkedHashMap<String, Integer>(16, 0.75f, true) {
            @Override
            protected boolean removeEldestEntry(Map.Entry<String, Integer> eldest) {
                return size() > 100; // Evict eldest when capacity exceeds 100
            }
        };

        // 3. TreeMap: O(log n) ops, sorted by key
        Map<String, Integer> treeMap = new TreeMap<>();
        treeMap.put("Zebra", 1);
        treeMap.put("Apple", 2);
        System.out.println(treeMap); // Prints {Apple=2, Zebra=1}
    }
}
